QUERY: SELECT DISTINCT AdmFName1, District FROM schools WHERE AdmFName1 IN (SELECT AdmFName1 FROM (SELECT AdmFName1, COUNT(CASE WHEN AdmFName1 IS NOT NULL THEN 1 END) as cnt FROM schools GROUP BY AdmFName1 ORDER BY cnt DESC LIMIT 2)) LIMIT 20;
